// Metadata Fingerprint Module - Production Ready
// Targets: Dropbox, Google Drive, OneDrive (multi-cloud API probe)
// Purpose: Harvest metadata via de-escalated OAuth tokens without file interaction
// Features: Pagination, rate limiting, recursive traversal, error handling, concurrency control

const axios = require('axios');
const pLimit = require('p-limit');

// Configuration Management
const config = {
  timeout: 30000,
  maxRetries: 3,
  retryDelay: 1000,
  rateLimit: {
    requestsPerSecond: 10,
    minInterval: 100
  },
  maxConcurrent: 5,
  pagination: {
    dropbox: 2000,
    googleDrive: 100,
    oneDrive: 200
  },
  logging: {
    timestamps: true,
    verbose: false
  }
};

// Logger utility
const logger = {
  info: (service, msg) => console.log(`[${new Date().toISOString()}] [${service}] INFO: ${msg}`),
  warn: (service, msg) => console.warn(`[${new Date().toISOString()}] [${service}] WARN: ${msg}`),
  error: (service, msg) => console.error(`[${new Date().toISOString()}] [${service}] ERROR: ${msg}`),
  debug: (service, msg) => config.logging.verbose && console.log(`[${new Date().toISOString()}] [${service}] DEBUG: ${msg}`)
};

// Rate limiter
class RateLimiter {
  constructor(requestsPerSecond) {
    this.minInterval = 1000 / requestsPerSecond;
    this.lastRequest = 0;
  }

  async acquire() {
    const now = Date.now();
    const timeSinceLastRequest = now - this.lastRequest;
    if (timeSinceLastRequest < this.minInterval) {
      await new Promise(resolve => setTimeout(resolve, this.minInterval - timeSinceLastRequest));
    }
    this.lastRequest = Date.now();
  }
}

const rateLimiter = new RateLimiter(config.rateLimit.requestsPerSecond);

// Input validation
function validateInput(service, token) {
  if (!token || typeof token !== 'string') {
    throw new Error('Invalid token: must be a non-empty string');
  }
  if (!service || !['dropbox', 'googleDrive', 'oneDrive'].includes(service)) {
    throw new Error(`Invalid service: ${service}. Must be one of: dropbox, googleDrive, oneDrive`);
  }
  if (token.length < 10) {
    throw new Error('Token appears invalid (too short)');
  }
}

// Exponential backoff retry logic
async function retryWithBackoff(fn, maxRetries = config.maxRetries, delay = config.retryDelay) {
  let lastError;
  for (let i = 0; i < maxRetries; i++) {
    try {
      await rateLimiter.acquire();
      return await fn();
    } catch (err) {
      lastError = err;
      if (!isRetryable(err) || i === maxRetries - 1) throw err;
      const backoffDelay = delay * Math.pow(2, i);
      logger.warn('retry', `Attempt ${i + 1} failed, retrying in ${backoffDelay}ms`);
      await new Promise(resolve => setTimeout(resolve, backoffDelay));
    }
  }
  throw lastError;
}

// Determine if error is retryable
function isRetryable(err) {
  if (!err.response) return true;
  const { status } = err.response;
  return status === 429 || status === 500 || status === 502 || status === 503 || status === 504;
}

// Service-specific configurations
const targets = {
  dropbox: {
    baseUrl: 'https://api.dropboxapi.com/2/files',
    endpoints: {
      listFolder: '/list_folder',
      listFolderContinue: '/list_folder/continue',
      getMetadata: '/get_metadata'
    },
    headers: token => ({
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    }),
    listPayload: {
      path: '',
      recursive: false,
      limit: config.pagination.dropbox
    }
  },
  googleDrive: {
    baseUrl: 'https://www.googleapis.com/drive/v3',
    endpoints: {
      listFiles: '/files'
    },
    headers: token => ({
      'Authorization': `Bearer ${token}`
    }),
    listParams: {
      pageSize: config.pagination.googleDrive,
      fields: 'nextPageToken, files(id, name, mimeType, modifiedTime, owners, size, webViewLink)',
      spaces: 'drive'
    }
  },
  oneDrive: {
    baseUrl: 'https://graph.microsoft.com/v1.0/me/drive',
    endpoints: {
      listRoot: '/root/children'
    },
    headers: token => ({
      'Authorization': `Bearer ${token}`
    })
  }
};

// Dropbox recursive traversal
async function dropboxTraverse(token, path = '', results = []) {
  const config_obj = targets.dropbox;
  try {
    const payload = {
      path: path,
      limit: config.pagination.dropbox
    };

    let hasMore = true;
    let cursor = null;

    while (hasMore) {
      let response;
      if (cursor) {
        response = await retryWithBackoff(() =>
          axios.post(
            config_obj.baseUrl + config_obj.endpoints.listFolderContinue,
            { cursor },
            { headers: config_obj.headers(token), timeout: config.timeout }
          )
        );
      } else {
        response = await retryWithBackoff(() =>
          axios.post(
            config_obj.baseUrl + config_obj.endpoints.listFolder,
            payload,
            { headers: config_obj.headers(token), timeout: config.timeout }
          )
        );
      }

      results.push(...response.data.entries);
      hasMore = response.data.has_more;
      cursor = response.data.cursor;
    }

    // Recursively traverse folders
    const limit = pLimit(config.maxConcurrent);
    const folderPromises = results
      .filter(entry => entry['.tag'] === 'folder')
      .map(folder => limit(() => dropboxTraverse(token, folder.path_display, results)));

    await Promise.all(folderPromises);
    return results;
  } catch (err) {
    logger.error('dropbox', `Traversal error: ${err.message}`);
    throw err;
  }
}

// Google Drive recursive traversal with pagination
async function googleDriveTraverse(token, parentId = 'root', results = []) {
  const config_obj = targets.googleDrive;
  try {
    let pageToken = null;

    do {
      const params = {
        ...config_obj.listParams,
        pageToken,
        q: `'${parentId}' in parents and trashed=false`
      };

      const response = await retryWithBackoff(() =>
        axios.get(
          config_obj.baseUrl + config_obj.endpoints.listFiles,
          { headers: config_obj.headers(token), params, timeout: config.timeout }
        )
      );

      results.push(...response.data.files);
      pageToken = response.data.nextPageToken;
    } while (pageToken);

    // Recursively traverse folders
    const limit = pLimit(config.maxConcurrent);
    const folderPromises = results
      .filter(file => file.mimeType === 'application/vnd.google-apps.folder')
      .map(folder => limit(() => googleDriveTraverse(token, folder.id, results)));

    await Promise.all(folderPromises);
    return results;
  } catch (err) {
    logger.error('googleDrive', `Traversal error: ${err.message}`);
    throw err;
  }
}

// OneDrive recursive traversal with pagination
async function oneDriveTraverse(token, itemId = 'root', results = []) {
  const config_obj = targets.oneDrive;
  try {
    let url = `${config_obj.baseUrl}/${itemId}/children`;
    let hasNextPage = true;

    while (hasNextPage) {
      const response = await retryWithBackoff(() =>
        axios.get(url, { headers: config_obj.headers(token), timeout: config.timeout })
      );

      results.push(...response.data.value);
      url = response.data['@odata.nextLink'];
      hasNextPage = !!url;
    }

    // Recursively traverse folders
    const limit = pLimit(config.maxConcurrent);
    const folderPromises = results
      .filter(item => item.folder && !item.deleted)
      .map(folder => limit(() => oneDriveTraverse(token, folder.id, results)));

    await Promise.all(folderPromises);
    return results;
  } catch (err) {
    logger.error('oneDrive', `Traversal error: ${err.message}`);
    throw err;
  }
}

// Main fingerprint service
async function fingerprintService(service, token, { recursive = true, limit_items = null } = {}) {
  try {
    validateInput(service, token);
    logger.info(service, `Starting metadata fingerprint (recursive: ${recursive})`);

    let metadata;

    if (service === 'dropbox') {
      metadata = recursive ? await dropboxTraverse(token) : await fingerprintServiceSingle(service, token);
    } else if (service === 'googleDrive') {
      metadata = recursive ? await googleDriveTraverse(token) : await fingerprintServiceSingle(service, token);
    } else if (service === 'oneDrive') {
      metadata = recursive ? await oneDriveTraverse(token) : await fingerprintServiceSingle(service, token);
    }

    // Apply item limit if specified
    if (limit_items && metadata.length > limit_items) {
      metadata = metadata.slice(0, limit_items);
      logger.warn(service, `Limited results to ${limit_items} items`);
    }

    logger.info(service, `Fingerprint complete. Retrieved ${metadata.length} items`);
    return metadata;
  } catch (err) {
    const errMsg = err.response?.data?.error || err.message;
    logger.error(service, `${err.response?.status || 'Unknown'} - ${errMsg}`);
    throw err;
  }
}

// Single-level fingerprint (non-recursive)
async function fingerprintServiceSingle(service, token) {
  const config_obj = targets[service];

  if (service === 'dropbox') {
    const response = await retryWithBackoff(() =>
      axios.post(
        config_obj.baseUrl + config_obj.endpoints.listFolder,
        config_obj.listPayload,
        { headers: config_obj.headers(token), timeout: config.timeout }
      )
    );
    return response.data.entries;
  } else if (service === 'googleDrive') {
    const response = await retryWithBackoff(() =>
      axios.get(
        config_obj.baseUrl + config_obj.endpoints.listFiles,
        { headers: config_obj.headers(token), params: config_obj.listParams, timeout: config.timeout }
      )
    );
    return response.data.files;
  } else if (service === 'oneDrive') {
    const response = await retryWithBackoff(() =>
      axios.get(
        config_obj.baseUrl + config_obj.endpoints.listRoot,
        { headers: config_obj.headers(token), timeout: config.timeout }
      )
    );
    return response.data.value;
  }
}

// Parallel scan multiple services
async function scanAllServices(tokens) {
  const limit = pLimit(config.maxConcurrent);
  const results = {};

  const promises = Object.entries(tokens).map(([service, token]) =>
    limit(async () => {
      try {
        results[service] = await fingerprintService(service, token, { recursive: true });
      } catch (err) {
        results[service] = { error: err.message };
      }
    })
  );

  await Promise.all(promises);
  return results;
}

// Export functions
module.exports = {
  fingerprintService,
  scanAllServices,
  config,
  logger,
  validateInput
};

// Example usage:
// const results = await fingerprintService('dropbox', '<OAuth_TOKEN>', { recursive: true, limit_items: 500 });
// const allResults = await scanAllServices({
//   dropbox: '<DROPBOX_TOKEN>',
//   googleDrive: '<GOOGLE_TOKEN>',
//   oneDrive: '<ONEDRIVE_TOKEN>'
// });

